package com.digitaladventure.dw2003.data

/** PAL status-resistance tables extracted from the game's Digimon profiles and SDIGIEDT enemy data. */
object StatusResistanceCatalog {
    private data class PartnerProfile(val formId: Int, val digimonId: Int, val values: List<Int>)

    private val partnerProfiles by lazy {
        PARTNER_DATA.split(';').map { row ->
            val values = row.split(',').map(String::toInt)
            PartnerProfile(values[0], values[1], values.drop(2))
        }
    }
    private val partnerByFormId by lazy { partnerProfiles.associateBy(PartnerProfile::formId) }
    private val partnerByDigimonId by lazy { partnerProfiles.associateBy(PartnerProfile::digimonId) }
    private val enemyById by lazy {
        ENEMY_DATA.split(';').associate { row ->
            val values = row.split(',').map(String::toInt)
            values.first() to values.drop(1)
        }
    }

    fun forPartner(profileId: Int, activeFormId: Int): List<Int> {
        val profile = if (activeFormId == 0 || activeFormId == 0xFFFF) {
            partnerByDigimonId[profileId + 1]
        } else {
            partnerByFormId[activeFormId]
        }
        return profile?.values ?: emptyList()
    }

    fun forEnemy(enemyId: Int): List<Int> = enemyById[enemyId].orEmpty()

